class TxnListAuditor {
    private static final Logger log = Logger.getLogger(TxnListAuditor.class.getName());

    // Slow/fast: slow lands at middle (2nd middle on even). O(n), O(1).
    TxnNode middleTransaction(TxnNode head) {
        TxnNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;          // +1
            fast = fast.next.next;     // +2
        }
        return slow;
    }
}

// ─── Would be in TxnNode.java in a real project ───
class TxnNode {
    final String id;
    TxnNode next;
    TxnNode(String id) { this.id = id; }
    static TxnNode of(String... ids) {
        TxnNode head = null, tail = null;
        for (String id : ids) {
            TxnNode n = new TxnNode(id);
            if (head == null) { head = tail = n; }
            else { tail.next = n; tail = n; }
        }
        return head;
    }
}

