// ─── File: src/main/java/com/bank/queue/TokenSorter.java ───
package com.bank.queue;

import java.util.Arrays;
import java.util.logging.Logger;

public class TokenSorter {

    private static final Logger log = Logger.getLogger(TokenSorter.class.getName());

    // values are a permutation of 1..n; sort in place, O(n) time, O(1) space
    public void cyclicSort(int[] nums) {
        int i = 0;
        while (i < nums.length) {
            int correct = nums[i] - 1;              // home index of this token
            if (nums[i] != nums[correct]) {         // guard against equal-value swap loop
                swap(nums, i, correct);             // send token to its home slot
            } else {
                i++;                                // already home, move on
            }
        }
        log.info(() -> "Sorted tokens = " + Arrays.toString(nums));
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}
