// ─── File: src/main/java/com/bank/locker/LockerAuditor.java ───
package com.bank.locker;

import java.util.logging.Logger;

public class LockerAuditor {

    private static final Logger log = Logger.getLogger(LockerAuditor.class.getName());

    // nums has n distinct values from [0, n]; return the missing one
    public int findMissing(int[] nums) {
        int n = nums.length;
        int i = 0;
        while (i < n) {
            if (nums[i] < n && nums[i] != nums[nums[i]]) {
                swap(nums, i, nums[i]);         // place value v at index v
            } else {
                i++;                            // value is n or already home
            }
        }
        for (int j = 0; j < n; j++) {
            if (nums[j] != j) {                 // first mismatch is the gap
                int missing = j;
                log.info(() -> "Missing key = " + missing);
                return missing;
            }
        }
        log.info(() -> "Missing key = " + n);   // all present ⇒ n is missing
        return n;
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}
