    // values in [1,n], duplicates allowed; return all missing values
    public List<Integer> findDisappeared(int[] nums) {
        int n = nums.length;
        int i = 0;
        while (i < n) {
            int correct = nums[i] - 1;              // home index of value v is v-1
            if (nums[i] != nums[correct]) {         // guard: skip equal-value swap
                swap(nums, i, correct);
            } else {
                i++;
            }
        }
        List<Integer> missing = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (nums[j] != j + 1) {                 // wrong slot ⇒ j+1 disappeared
                missing.add(j + 1);
            }
        }
        log.info(() -> "Disappeared serials = " + missing);
        return missing;
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}
