package com.bank.txn;

import java.util.logging.Logger;

public class DuplicateFinder {

    private static final Logger log = Logger.getLogger(DuplicateFinder.class.getName());

    // n+1 values in [1,n]; find the repeated one WITHOUT modifying the array
    public int findDuplicate(int[] nums) {
        int slow = nums[0];
        int fast = nums[0];
        do {                                        // phase 1: find meeting point
            slow = nums[slow];
            fast = nums[nums[fast]];
        } while (slow != fast);

        slow = nums[0];                             // phase 2: find cycle entry
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[fast];
        }
        int dup = slow;
        log.info(() -> "Duplicate transaction ID = " + dup);
        return dup;                                 // cycle entry = duplicate
    }
}
