package com.bank.accountid;

import java.util.logging.Logger;

public class AccountIdAllocator {

    private static final Logger log = Logger.getLogger(AccountIdAllocator.class.getName());

    // smallest missing positive; ignores negatives, zeros, out-of-range values
    public int firstMissingPositive(int[] nums) {
        int n = nums.length;
        int i = 0;
        while (i < n) {
            int v = nums[i];
            if (v > 0 && v <= n && nums[i] != nums[v - 1]) {
                swap(nums, i, v - 1);               // place v at index v-1 if valid
            } else {
                i++;                                // junk or already home
            }
        }
        for (int j = 0; j < n; j++) {
            if (nums[j] != j + 1) {                 // first empty slot
                int ans = j + 1;
                log.info(() -> "First missing positive = " + ans);
                return ans;
            }
        }
        log.info(() -> "First missing positive = " + (n + 1));
        return n + 1;                               // all of 1..n present
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}
