package com.bank.atm;

import java.util.logging.Logger;

public class StatusWordCodec {

    private static final Logger log = Logger.getLogger(StatusWordCodec.class.getName());

    // reverse all 32 bits of the status word
    public int reverseBits(int n) {
        int result = 0;
        int work = n;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (work & 1);    // make room, append lowest bit
            work >>>= 1;                            // unsigned shift: zero-fill
        }
        int reversed = result;
        log.info(() -> "Reversed word = " + Integer.toBinaryString(reversed));
        return reversed;
    }
}
