public class StatementPageChecker {

    private static final Logger log = Logger.getLogger(StatementPageChecker.class.getName());

    // n distinct values from [0,n]; XOR indices with values, survivor is missing
    public int findMissing(int[] pages) {
        int missing = pages.length;                 // seed with n (top index)
        for (int i = 0; i < pages.length; i++) {
            missing ^= i ^ pages[i];                // fold index and value together
        }
        int result = missing;
        log.info(() -> "Missing page = " + result);
        return result;
    }
