package com.bank.accumulator;

import java.util.logging.Logger;

public class BitwiseAccumulator {

    private static final Logger log = Logger.getLogger(BitwiseAccumulator.class.getName());

    // add two integers using only bitwise operators
    public int add(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1;               // carries, shifted one position left
            a = a ^ b;                              // sum without carry
            b = carry;                              // fold carry back in
        }
        int sum = a;
        log.info(() -> "Bitwise sum = " + sum);
        return sum;
    }
}
