package com.bank.slip;

import java.util.Arrays;
import java.util.logging.Logger;

public class SlipSorter {

    private static final Logger log = Logger.getLogger(SlipSorter.class.getName());

    public void bubbleSort(int[] a) {
        for (int i = 0; i < a.length - 1; i++) {
            boolean swapped = false;
            for (int j = 0; j < a.length - 1 - i; j++) {
                if (a[j] > a[j + 1]) { swap(a, j, j + 1); swapped = true; }
            }
            if (!swapped) break;                    // already sorted, stop early
        }
        log.info(() -> "Bubble → " + Arrays.toString(a));
    }

    public void selectionSort(int[] a) {
        for (int i = 0; i < a.length - 1; i++) {
            int min = i;
            for (int j = i + 1; j < a.length; j++) if (a[j] < a[min]) min = j;
            swap(a, i, min);                        // exactly n-1 swaps
        }
        log.info(() -> "Selection → " + Arrays.toString(a));
    }

    public void insertionSort(int[] a) {
        for (int i = 1; i < a.length; i++) {
            int key = a[i], j = i - 1;
            while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }   // shift right
            a[j + 1] = key;                         // slot the key into place
        }
        log.info(() -> "Insertion → " + Arrays.toString(a));
    }

    private void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}
