package com.bank.ledger;

import java.util.Arrays;
import java.util.logging.Logger;

public class LedgerMerger {

    private static final Logger log = Logger.getLogger(LedgerMerger.class.getName());

    public void mergeSort(int[] a) {
        if (a.length < 2) return;
        sort(a, 0, a.length - 1, new int[a.length]);
        log.info(() -> "Merge sorted → " + Arrays.toString(a));
    }

    private void sort(int[] a, int lo, int hi, int[] temp) {
        if (lo >= hi) return;                       // single element, sorted
        int mid = lo + (hi - lo) / 2;
        sort(a, lo, mid, temp);                     // sort left half
        sort(a, mid + 1, hi, temp);                 // sort right half
        merge(a, lo, mid, hi, temp);                // merge the two runs
    }

    private void merge(int[] a, int lo, int mid, int hi, int[] temp) {
        int i = lo, j = mid + 1, k = lo;
        while (i <= mid && j <= hi) {
            temp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];   // <= keeps it stable
        }
        while (i <= mid) temp[k++] = a[i++];
        while (j <= hi) temp[k++] = a[j++];
        System.arraycopy(temp, lo, a, lo, hi - lo + 1);     // copy back
    }
}
