package com.bank.risk;

import java.util.Arrays;
import java.util.Random;
import java.util.logging.Logger;

public class BalanceSorter {

    private static final Logger log = Logger.getLogger(BalanceSorter.class.getName());
    private final Random rnd = new Random();

    public void quickSort(int[] a) {
        sort(a, 0, a.length - 1);
        log.info(() -> "Quick sorted → " + Arrays.toString(a));
    }

    private void sort(int[] a, int lo, int hi) {
        if (lo >= hi) return;
        int p = partition(a, lo, hi);               // pivot now in final place
        sort(a, lo, p - 1);                         // sort left side
        sort(a, p + 1, hi);                         // sort right side
    }

    private int partition(int[] a, int lo, int hi) {
        int r = lo + rnd.nextInt(hi - lo + 1);      // randomized pivot
        swap(a, r, hi);                             // move pivot to end
        int pivot = a[hi], i = lo;
        for (int j = lo; j < hi; j++) {
            if (a[j] < pivot) swap(a, i++, j);      // smaller go left of boundary
        }
        swap(a, i, hi);                             // place pivot at boundary
        return i;
    }

    private void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}
