package com.bank.settlementheap;

import java.util.Arrays;
import java.util.logging.Logger;

public class SettlementHeapSorter {

    private static final Logger log = Logger.getLogger(SettlementHeapSorter.class.getName());

    public void heapSort(int[] a) {
        int n = a.length;
        for (int i = n / 2 - 1; i >= 0; i--) siftDown(a, i, n);   // build max-heap O(n)
        for (int end = n - 1; end > 0; end--) {
            swap(a, 0, end);                        // move current max to the end
            siftDown(a, 0, end);                    // restore heap on shrunk range
        }
        log.info(() -> "Heap sorted → " + Arrays.toString(a));
    }

    private void siftDown(int[] a, int i, int size) {
        while (true) {
            int largest = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < size && a[l] > a[largest]) largest = l;
            if (r < size && a[r] > a[largest]) largest = r;
            if (largest == i) break;                // heap property satisfied
            swap(a, i, largest);
            i = largest;                            // continue sifting down
        }
    }

    private void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}
