package com.bank.priority;

import java.util.Arrays;
import java.util.logging.Logger;

public class PriorityCountingSorter {

    private static final Logger log = Logger.getLogger(PriorityCountingSorter.class.getName());

    // stable counting sort for keys in [0, k-1]
    public int[] countingSort(int[] a, int k) {
        int[] count = new int[k];
        for (int x : a) count[x]++;                 // tally frequencies
        for (int i = 1; i < k; i++) count[i] += count[i - 1];   // prefix sums
        int[] out = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {   // right to left ⇒ stable
            out[--count[a[i]]] = a[i];
        }
        log.info(() -> "Counting sorted → " + Arrays.toString(out));
        return out;
    }

    // radix sort for non-negative integers using stable counting per digit
    public int[] radixSort(int[] a) {
        int max = Arrays.stream(a).max().orElse(0);
        int[] cur = a.clone();
        for (int exp = 1; max / exp > 0; exp *= 10) {
            cur = countByDigit(cur, exp);           // stable pass per digit
        }
        int[] result = cur;
        log.info(() -> "Radix sorted → " + Arrays.toString(result));
        return result;
    }

    private int[] countByDigit(int[] a, int exp) {
        int[] count = new int[10];
        for (int x : a) count[(x / exp) % 10]++;
        for (int i = 1; i < 10; i++) count[i] += count[i - 1];
        int[] out = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {
            int d = (a[i] / exp) % 10;
            out[--count[d]] = a[i];
        }
        return out;
    }
}
