package com.bank.routing;

import java.util.*;
import java.util.logging.Logger;

public class PaymentRouter {

    private static final Logger log = Logger.getLogger(PaymentRouter.class.getName());

    // adj[u] = list of {v, weight}; returns min cost from src to every node
    public int[] shortestCost(List<int[]>[] adj, int src) {
        int n = adj.length;
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(x -> x[1]));
        pq.add(new int[]{src, 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int u = top[0], d = top[1];
            if (d > dist[u]) continue;              // stale entry, skip (lazy delete)
            for (int[] edge : adj[u]) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {        // relax edge u→v
                    dist[v] = dist[u] + w;
                    pq.add(new int[]{v, dist[v]});
                }
            }
        }
        log.info(() -> "Min costs from " + src + " = " + Arrays.toString(dist));
        return dist;
    }
}
