package com.bank.fx;

import java.util.Arrays;
import java.util.logging.Logger;

public class FxArbitrageDetector {

    private static final Logger log = Logger.getLogger(FxArbitrageDetector.class.getName());
    private static final int INF = Integer.MAX_VALUE;

    // edges: array of {u, v, weight}; returns dist[] or null if negative cycle
    public int[] shortestPaths(int V, int[][] edges, int src) {
        int[] dist = new int[V];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        for (int i = 1; i < V; i++) {               // V-1 relaxation passes
            for (int[] e : edges) {
                if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]]) {
                    dist[e[1]] = dist[e[0]] + e[2];  // relax edge u→v
                }
            }
        }
        for (int[] e : edges) {                     // V-th pass: detect neg cycle
            if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]]) {
                log.severe("Negative cycle detected (arbitrage)");
                return null;
            }
        }
        log.info(() -> "Shortest costs from " + src + " = " + Arrays.toString(dist));
        return dist;
    }
}
