package com.bank.broadcast;

import java.util.*;
import java.util.logging.Logger;

public class RateBroadcastService {

    private static final Logger log = Logger.getLogger(RateBroadcastService.class.getName());

    // times: {u, v, w}; nodes 1..n; k = source; return max shortest delay or -1
    public int networkDelayTime(int[][] times, int n, int k) {
        List<int[]>[] adj = new List[n + 1];
        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();
        for (int[] t : times) adj[t[0]].add(new int[]{t[1], t[2]});

        int[] dist = new int[n + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[k] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(x -> x[1]));
        pq.add(new int[]{k, 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int u = top[0], d = top[1];
            if (d > dist[u]) continue;              // skip stale entry
            for (int[] e : adj[u]) {
                if (dist[u] + e[1] < dist[e[0]]) {
                    dist[e[0]] = dist[u] + e[1];    // relax edge
                    pq.add(new int[]{e[0], dist[e[0]]});
                }
            }
        }
        int ans = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[i] == Integer.MAX_VALUE) {     // unreachable branch
                log.severe("Node " + i + " unreachable; rollout incomplete");
                return -1;
            }
            ans = Math.max(ans, dist[i]);           // slowest-reached node sets total
        }
        int result = ans;
        log.info(() -> "Network delay time = " + result);
        return result;
    }
}
