package com.bank.fraudkmp;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class FraudPatternMatcher {

    private static final Logger log = Logger.getLogger(FraudPatternMatcher.class.getName());

    public List<Integer> search(String text, String pattern) {
        List<Integer> hits = new ArrayList<>();
        int n = text.length(), m = pattern.length();
        if (m == 0) return hits;
        int[] lps = buildLps(pattern);
        int i = 0, j = 0;
        while (i < n) {
            if (text.charAt(i) == pattern.charAt(j)) {
                i++; j++;
                if (j == m) {                       // full match ending at i-1
                    hits.add(i - j);
                    j = lps[j - 1];                 // continue for overlaps
                }
            } else if (j > 0) {
                j = lps[j - 1];                     // jump via prefix table
            } else {
                i++;                                // no prefix to fall back to
            }
        }
        log.info(() -> "Signature found at indices " + hits);
        return hits;
    }

    private int[] buildLps(String p) {
        int m = p.length();
        int[] lps = new int[m];
        int len = 0;
        for (int i = 1; i < m; i++) {
            while (len > 0 && p.charAt(i) != p.charAt(len)) len = lps[len - 1];
            if (p.charAt(i) == p.charAt(len)) len++;
            lps[i] = len;                           // longest prefix==suffix
        }
        return lps;
    }
}
