package com.bank.watchlist;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class WatchlistScanner {

    private static final Logger log = Logger.getLogger(WatchlistScanner.class.getName());
    private static final int BASE = 256;
    private static final long PRIME = 1_000_000_007L;

    public List<Integer> search(String text, String pattern) {
        List<Integer> hits = new ArrayList<>();
        int n = text.length(), m = pattern.length();
        if (m == 0 || m > n) return hits;

        long patHash = 0, winHash = 0, high = 1;
        for (int i = 0; i < m - 1; i++) high = (high * BASE) % PRIME;  // base^(m-1)
        for (int i = 0; i < m; i++) {
            patHash = (BASE * patHash + pattern.charAt(i)) % PRIME;
            winHash = (BASE * winHash + text.charAt(i)) % PRIME;
        }
        for (int i = 0; i <= n - m; i++) {
            if (patHash == winHash && text.regionMatches(i, pattern, 0, m)) {
                hits.add(i);                        // verified true match
            }
            if (i < n - m) {                        // roll the window forward
                winHash = (BASE * (winHash - text.charAt(i) * high) + text.charAt(i + m)) % PRIME;
                if (winHash < 0) winHash += PRIME;  // keep non-negative
            }
        }
        log.info(() -> "Watchlist matches at " + hits);
        return hits;
    }
}
