package com.bank.search;

import java.util.logging.Logger;

public class SearchStrategySelector {

    private static final Logger log = Logger.getLogger(SearchStrategySelector.class.getName());

    public int bruteForce(String text, String pattern) {
        int n = text.length(), m = pattern.length();
        for (int i = 0; i <= n - m; i++) {
            int j = 0;
            while (j < m && text.charAt(i + j) == pattern.charAt(j)) j++;
            if (j == m) return i;                   // match at i
        }
        return -1;                                  // O(n*m), no preprocessing
    }

    public int kmp(String text, String pattern) {
        int n = text.length(), m = pattern.length();
        int[] lps = new int[m];
        int len = 0;
        for (int i = 1; i < m; i++) {
            while (len > 0 && pattern.charAt(i) != pattern.charAt(len)) len = lps[len - 1];
            if (pattern.charAt(i) == pattern.charAt(len)) len++;
            lps[i] = len;
        }
        int i = 0, j = 0;
        while (i < n) {
            if (text.charAt(i) == pattern.charAt(j)) { i++; j++; if (j == m) return i - j; }
            else if (j > 0) j = lps[j - 1];
            else i++;
        }
        return -1;                                  // guaranteed O(n+m)
    }

    // choose strategy based on input characteristics
    public String choose(int patternLen, int numPatterns, boolean needWorstCase) {
        String pick;
        if (patternLen <= 8 && numPatterns == 1) pick = "brute-force";
        else if (numPatterns > 1) pick = "rabin-karp";
        else if (needWorstCase) pick = "kmp";
        else pick = "library-indexOf";
        log.info(() -> "Chosen strategy = " + pick);
        return pick;
    }
}
