package com.bank.grid;

import java.util.Arrays;
import java.util.logging.Logger;

public class GridReportRotator {

    private static final Logger log = Logger.getLogger(GridReportRotator.class.getName());

    // rotate n×n matrix 90° clockwise in place
    public void rotate90Clockwise(int[][] m) {
        int n = m.length;
        for (int i = 0; i < n; i++) {               // transpose: swap across diagonal
            for (int j = i + 1; j < n; j++) {
                int t = m[i][j];
                m[i][j] = m[j][i];
                m[j][i] = t;
            }
        }
        for (int[] row : m) {                       // reverse each row
            int l = 0, r = n - 1;
            while (l < r) {
                int t = row[l];
                row[l++] = row[r];
                row[r--] = t;
            }
        }
        log.info(() -> "Rotated grid → " + Arrays.deepToString(m));
    }
}
