package com.bank.ticker;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class AtmGridTicker {

    private static final Logger log = Logger.getLogger(AtmGridTicker.class.getName());

    // return all elements in clockwise spiral order
    public List<Integer> spiralOrder(int[][] m) {
        List<Integer> out = new ArrayList<>();
        if (m.length == 0) return out;
        int top = 0, bottom = m.length - 1, left = 0, right = m[0].length - 1;
        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) out.add(m[top][j]);     // top row →
            top++;
            for (int i = top; i <= bottom; i++) out.add(m[i][right]);   // right col ↓
            right--;
            if (top <= bottom) {                                        // guard
                for (int j = right; j >= left; j--) out.add(m[bottom][j]); // bottom ←
                bottom--;
            }
            if (left <= right) {                                        // guard
                for (int i = bottom; i >= top; i--) out.add(m[i][left]); // left col ↑
                left++;
            }
        }
        log.info(() -> "Spiral order → " + out);
        return out;
    }
}
